6.1 天气MCP Server 这个Server只暴露一个get_weather工具，背后调用免费的wttr.in服务（无需API Key，便于演示）。同样用FastMCP，几十行搞定： # weather_mcp_server.py # 天气查询 MCP Server：暴露 get_weather 工具 # 依赖：pip install mcp httpx # 运行：python weather_mcp_server.py import httpx from mcp.server.fastmcp import FastMCP mcp = FastMCP("weather-mcp") # wttr.in 是免费天气服务，?format=j1 返回 JSON WEATHER_URL = "https://wttr.in/{city}?format=j1" @mcp.tool() async def get_weather(city: str) -> str: """查询指定城市的当前天气，返回温度、天气状况、湿度、风速等。 城市名用英文或拼音，例如 Beijing、shanghai。""" try: async with httpx.AsyncClient(timeout=10) as client: resp = await client.get(WEATHER_URL.format(city=city)) resp.raise_for_status() data = resp.json() # 解析当前天气字段 current = data["current_condition"][0] temp_c = current["temp_C"] desc = current["weatherDesc"][0]["value"] humidity = current["humidity"] wind = current["windspeedKmph"] return ( f"城市：{city}
" f"温度：{temp_c}°C
" f"天气：{desc}
" f"湿度：{humidity}%
" f"风速：{wind}km/h" ) except Exception as e: return f"查询失败：{e}" if __name__ == "__main__": mcp.run() 💡 小贴士：为什么用httpx.AsyncClient而不是requests？ MCP的Python SDK基于asyncio异步框架。如果工具内部用同步的requests发请求，会阻塞整个事件循环，导致Server卡住无法响应其他调用。httpx的异步客户端与asyncio天然兼容，不会阻塞。同理，访问数据库应该用aiosqlite、asyncpg等异步驱动。

6.2.4 完整Python实现 下面我们用纯 Python（不用任何框架）实现一个完整的 ReAct 推理引擎。代码分三部分：工具定义（智能体能用什么）、提示模板（告诉模型怎么输出）、主循环（驱动 Thought-Action-Observation 循环）。模型用 gpt-5.4，通过 OpenAI 兼容接口调用。 # react_agent.py # ReAct 推理引擎的纯 Python 实现，不依赖任何框架 import re from typing import Callable from openai import OpenAI client = OpenAI() # 默认从环境变量 OPENAI_API_KEY 读取密钥 MODEL = "gpt-5.4" MAX_STEPS = 10 # 安全阀：防止智能体陷入无限循环 # ---------- 工具定义 ---------- def search_wiki(query: str) -> str: """模拟维基百科检索工具，实际项目可替换为真实API""" fake_db = { "北京": "北京是中华人民共和国首都，常住人口约2189万（2020年）。", "上海": "上海是中国直辖市，GDP居中国城市首位（2023年约4.72万亿元）。", "深圳": "深圳是中国经济特区之一，位于广东省，常住人口约1768万。", } # 简单的关键词匹配，实际项目用向量检索或API for key, val in fake_db.items(): if key in query: return val return f"未找到与'{query}'相关的信息。" def calculate(expression: str) -> str: """安全计算器工具，支持基本四则运算""" try: # 只允许数字和运算符，防止代码注入 if not re.match(r'^[\d\s+\-*/().]+$', expression): return "错误：表达式包含非法字符" # ⚠️ eval 有安全风险，这里靠正则白名单防护；生产环境建议用 ast.literal_eval result = eval(expression, {"__builtins__": {}}, {}) return f"{expression} = {result}" except Exception as e: return f"计算错误：{e}" # 工具注册表：名字 -> (函数, 描述, 参数说明) # 智能体通过这张表知道"自己有哪些工具、每个工具怎么用" TOOLS: dict[str, tuple[Callable, str, str]] = { "search_wiki": (search_wiki, "检索维基百科获取城市信息", "query: 检索关键词"), "calculate": (calculate, "执行四则运算", "expression: 数学表达式字符串"), } # ---------- 提示模板 ---------- # 这是 ReAct 的"灵魂"——用提示词教模型按固定格式输出 Thought 和 Action REACT_PROMPT = """你是一个使用 ReAct 模式推理的智能体。 可用工具： {tool_desc} 请严格按以下格式输出，每一步包含两行： Thought: 你的推理过程，解释为什么这么做 Action: 工具名(参数) （系统会返回 Observation，然后你继续下一轮 Thought） 当任务完成时，输出： Thought: 任务已完成的推理 Action: Finish(最终答案) 任务：{task} {history} Thought:""" def build_tool_desc() -> str: """构造工具描述文本，注入提示模板""" lines = [] for name, (_, desc, params) in TOOLS.items(): lines.append(f"- {name}: {desc}，参数：{params}") return "
".join(lines) def parse_action(text: str) -> tuple[str, str]: """从模型输出中解析出 Action 名和参数，例如 search_wiki(北京)""" # 用正则匹配 "Action: 工具名(参数)" 的格式 match = re.search(r'Action:\s*(\w+)\((.*)\)', text) if not match: # 解析失败：可能是模型没按格式输出，直接当作最终答案返回 return "Finish", text return match.group(1), match.group(2) def run_tool(action_name: str, args: str) -> str: """执行工具调用，返回结果字符串""" if action_name == "Finish": return args # Finish 不调用工具，直接返回最终答案 if action_name not in TOOLS: return f"错误：未知工具 {action_name}" func, _, _ = TOOLS[action_name] try: # 简单参数解析：去掉首尾引号后直接传入 args = args.strip().strip('"').strip("'") return func(args) except Exception as e: return f"工具执行错误：{e}" def call_llm(prompt: str) -> str: """调用大模型，返回文本""" resp = client.chat.completions.create( model=MODEL, messages=[{"role": "user", "content": prompt}], temperature=0, # 推理任务用低温度，保证输出稳定可复现 ) return resp.choices[0].message.content def react_agent(task: str) -> str: """ReAct 主循环：Thought → Action → Observation → 重复""" history = "" # 累积的推理轨迹，每轮都塞进提示让模型"看到"完整历史 for step in range(MAX_STEPS): # 构造提示：工具描述 + 任务 + 历史轨迹 prompt = REACT_PROMPT.format( tool_desc=build_tool_desc(), task=task, history=history, ) # 提示模板末尾预留了 "Thought:"，模型会从这里自然续写推理过程 output = call_llm(prompt).strip() # 把模型输出拼回历史轨迹（包含它写的 Thought 和 Action） history += output + "
" # 解析出动作名和参数 action_name, args = parse_action(output) print(f"[Step {step+1}] Action: {action_name}({args})") # 如果模型说 Finish，任务完成，返回最终答案 if action_name == "Finish": return args # 否则执行工具，把结果作为 Observation 拼回历史 observation = run_tool(action_name, args) history += f"Observation: {observation}
" print(f"[Step {step+1}] Observation: {observation}
") return "达到最大步数，任务未完成。" 💡 小贴士： MAX_STEPS 是安全阀——没有它，模型可能无限循环"再查一下”。生产环境建议配合超时机制。 temperature=0 让推理过程稳定可复现，调试阶段尤其重要：同样的输入应该产出同样的轨迹。 eval 有安全风险，这里靠正则白名单防护。生产环境务必换成 ast.literal_eval 或专门的数学表达式解析库。

4.4.3 自一致性（Self-Consistency） CoT有一个隐患：同一条推理路径可能因为某个中间步骤错误而导致最终答案错误。比如模型某一步把3+3算成了7，后面就全错。 **自一致性（Self-Consistency）**的思路是：让模型用高温度生成多条不同的推理路径，然后对最终答案做投票，取出现次数最多的作为结果。生活里这就像你拿不准一道题，问了5个同学，5个里有3个说答案是12，那大概率就是12。 # self_consistency.py # 自一致性提升CoT的稳定性 from collections import Counter from openai import OpenAI client = OpenAI() def solve_with_self_consistency(question: str, n: int = 5) -> str: """生成n条推理路径，投票选出最终答案""" prompt = f"{question}

请一步一步思考，最后用'答案是：X'的格式给出答案。" answers = [] for _ in range(n): response = client.chat.completions.create( model="gpt-5.4", messages=[{"role": "user", "content": prompt}], temperature=0.7, # 高温度保证路径多样性 max_tokens=500, ) text = response.choices[0].message.content # 简单提取答案：从"答案是："后面取 if "答案是：" in text: ans = text.split("答案是：")[-1].strip().split("
")[0] answers.append(ans) # 投票：统计每个答案出现次数，取最多的 if not answers: return "无法确定答案" counter = Counter(answers) best, _ = counter.most_common(1)[0] # 取票数最高的答案 return f"答案：{best}（{n}次推理中{counter[best]}次一致）" # 测试 question = "一个数列：2, 6, 12, 20, 30, ...，请问第10项是多少？" print(solve_with_self_consistency(question, n=5)) 自一致性以n倍的推理成本换取更高的准确率，适合对正确性要求高、对延迟不敏感的场景（如离线数据分析）。在线对话场景建议用更小的n（如3），否则用户等不及。 💡 temperature和Self-Consistency的关系：Self-Consistency必须配高temperature（0.7左右）才有意义。如果temperature=0，n次推理结果几乎一模一样，投票就没意义了。

5.3 这段代码做了什么 下面实现一个简化版 Plan-and-Execute。plan() 让LLM把任务拆成JSON数组形式的子任务清单；execute() 逐个执行子任务并把已完成的上下文带进去；最后再让LLM把所有子任务结果汇总成最终答案。 # file: level3_plan_execute.py # Plan-and-Execute架构智能体 import os import json from openai import OpenAI client = OpenAI(api_key=os.environ.get("OPENAI_API_KEY")) PLANNER_PROMPT = """你是一个任务规划器。请将用户任务拆分为有序的子任务列表。 每个子任务应可独立执行，粒度适中（不多于5个子任务）。 仅输出JSON数组，不要其他文字，格式如： ["子任务1", "子任务2"] 用户任务：{task} """ EXECUTOR_PROMPT = """你是一个任务执行器。请完成以下子任务。 你可以使用如下已知能力：搜索、计算、翻译、写作。 若需要外部信息，可基于常识合理假设并在结果中标注"假设"。 仅输出执行结果，不要解释过程。 子任务：{subtask} 上下文（已完成结果）：{context} """ def plan(task: str) -> list: """生成子任务计划：让LLM输出JSON数组""" resp = client.chat.completions.create( model="gpt-5.4", messages=[{"role": "user", "content": PLANNER_PROMPT.format(task=task)}], temperature=0.2, # 规划阶段低温度，让拆解更稳定 ) raw = resp.choices[0].message.content.strip() try: return json.loads(raw) # 把JSON文本解析成Python列表 except json.JSONDecodeError: # 解析失败则退化为单任务，保证不崩 return [task] def execute(subtask: str, context: str) -> str: """执行单个子任务，带上已完成结果作为上下文""" resp = client.chat.completions.create( model="gpt-5.4", messages=[{"role": "user", "content": EXECUTOR_PROMPT.format( subtask=subtask, context=context )}], temperature=0.3, ) return resp.choices[0].message.content.strip() def plan_execute_agent(task: str) -> str: """Plan-and-Execute主流程：规划→执行→汇总""" # 1. 规划：拆出子任务清单 subtasks = plan(task) print(f"计划：{subtasks}") # 2. 依次执行，并累积上下文（后面的子任务能看到前面的结果） context_parts = [] for i, st in enumerate(subtasks, 1): result = execute(st, "
".join(context_parts)) context_parts.append(f"[{i}] {st} -> {result}") # 拼进上下文 print(f"执行[{i}]：{st}
结果：{result}
") # 3. 汇总：让LLM把所有子任务结果整理成最终答案 summary_prompt = f"请根据以下子任务结果，回答原始任务：
原始任务：{task}
子任务结果：
" + "
".join(context_parts) resp = client.chat.completions.create( model="gpt-5.4", messages=[{"role": "user", "content": summary_prompt}], temperature=0.3, ) return resp.choices[0].message.content.strip() if __name__ == "__main__": print(plan_execute_agent("帮我调研Python和Rust在Web开发中的优劣，并给出学习建议。")) 💡 小贴士：让LLM输出JSON时，加一句"仅输出JSON，不要其他文字"能大幅提高解析成功率。如果模型支持 response_format={"type": "json_object"}，用它会更加稳。 ⚠️ 注意事项：Planner 拆出的子任务可能粒度不均——有时太粗（一个子任务啥都包了），有时太碎（拆成20条）。可以通过提示词约束"3~5个、每个可独立完成"来缓解。

11.3.5 代码示例：评估框架实现 下面我们实现一个轻量但可扩展的评估框架。它的设计思路是"可组合"——每条用例可以同时触发多种评估方法，最终通过加权综合得出一个总分，就像学生期末成绩由笔试、实验、口试按权重汇总。 # eval_framework.py """AI 智能体评估框架：支持端到端、步骤级与 LLM-as-Judge 评估""" from __future__ import annotations from dataclasses import dataclass, field from typing import Callable, Optional import time import json @dataclass class AgentOutput: """智能体单次运行的完整产出（一次"答题"的全部信息）""" answer: str # 最终答案 steps: list[dict] # 中间步骤 Trace（草稿纸） tool_calls: list[dict] # 工具调用记录 token_usage: dict # Token 统计 latency: float # 端到端延迟（秒） @dataclass class TestCase: """单条测试用例（一道"考题"）""" case_id: str user_input: str expected: Optional[str] = None # 严格匹配的预期答案 expected_tools: Optional[list[str]] = None # 期望调用的工具 success_criteria: Optional[Callable] = None # 自定义成功判据 @dataclass class EvalResult: """单条评估结果（一张"批改单"）""" case_id: str passed: bool score: float # 0~1 分 metrics: dict = field(default_factory=dict) detail: str = "" class Evaluator: """评估器：组合多种评估方法（一位"多面手阅卷老师"）""" def __init__(self, judge_llm: Optional[Callable] = None): # judge_llm 是一个可调用对象：传入 prompt 文本，返回模型回答 self.judge_llm = judge_llm def eval_end_to_end(self, case: TestCase, output: AgentOutput) -> EvalResult: """端到端评估：严格匹配 + 自定义判据""" # 先收集通用指标：Token、延迟、步数 metrics = {"token_total": output.token_usage.get("total", 0), "latency": output.latency, "step_count": len(output.steps)} # 分支1：严格匹配——逐字符比对 if case.expected is not None: passed = output.answer.strip() == case.expected.strip() score = 1.0 if passed else 0.0 return EvalResult(case.case_id, passed, score, metrics, "strict_match") # 分支2：自定义判据——交给用例自带的判定函数 if case.success_criteria is not None: return case.success_criteria(case, output) # 分支3：默认——有非空答案就算通过 return EvalResult(case.case_id, bool(output.answer), 1.0, metrics, "non_empty") def eval_tool_calls(self, case: TestCase, output: AgentOutput) -> EvalResult: """工具调用准确率评估：用 precision / recall / F1 综合衡量""" if not case.expected_tools: # 没有期望工具时无法评估，默认满分 return EvalResult(case.case_id, True, 1.0, {}, "no_expected_tools") # 实际调用过的工具名列表（保留重复，用于算 precision） actual = [c["tool"] for c in output.tool_calls] expected = set(case.expected_tools) # 期望工具去重 hit = sum(1 for t in actual if t in expected) # 命中数：实际中属于期望的 # precision = 命中 / 实际调用（越多冗余调用，precision 越低） precision = hit / len(actual) if actual else 0 # recall = 命中 / 期望数量（漏调用越多，recall 越低） recall = hit / len(expected) if expected else 1 # F1 = 精确率与召回率的调和平均，综合衡量 f1 = 2 * precision * recall / (precision + recall) if (precision + recall) else 0 return EvalResult(case.case_id, f1 >= 0.8, f1, {"precision": precision, "recall": recall}, "tool_f1") def eval_llm_judge(self, case: TestCase, output: AgentOutput, rubric: str = "准确性、相关性、完整性") -> EvalResult: """LLM-as-Judge：开放式评分""" if not self.judge_llm: # 没有注入评审模型时跳过，返回 0 分 return EvalResult(case.case_id, False, 0.0, {}, "no_judge") # 构造评审 prompt，要求只返回 JSON 便于解析 prompt = ( f"你是一位严格的评审。请按以下维度评分（0~1）：{rubric}
" f"用户问题：{case.user_input}
" f"智能体回答：{output.answer}
" f"请只返回 JSON：{{"score": float, "reason": str}}" ) try: raw = self.judge_llm(prompt) # 调用评审 LLM data = json.loads(raw) # 解析 JSON 返回 score = float(data.get("score", 0)) return EvalResult(case.case_id, score >= 0.7, score, {"reason": data.get("reason", "")}, "llm_judge") except Exception as e: # 评审失败要兜底，不能让整个评估崩溃 return EvalResult(case.case_id, False, 0.0, {"error": str(e)}, "judge_error") def run_eval(agent_fn: Callable, evaluator: Evaluator, cases: list[TestCase]) -> list[EvalResult]: """执行评估：对每条用例运行智能体并评估""" results = [] for case in cases: t0 = time.time() output = agent_fn(case.user_input) # 运行被测智能体 output.latency = time.time() - t0 # 记录端到端延迟 # 组合多种评估：端到端、工具、LLM 评审 r1 = evaluator.eval_end_to_end(case, output) r2 = evaluator.eval_tool_calls(case, output) r3 = evaluator.eval_llm_judge(case, output) # 综合得分：加权平均（权重之和=1.0） # 0.5 端到端 + 0.2 工具 + 0.3 评审，可根据业务调整 r1.score = 0.5 * r1.score + 0.2 * r2.score + 0.3 * r3.score r1.passed = r1.score >= 0.7 # 0.7 为通过阈值 # 把工具与评审的子指标合并进总 metrics r1.metrics.update(r2.metrics) r1.metrics.update(r3.metrics) results.append(r1) return

Node.js 实现：一个实时价格推送服务 先来一个最直观的例子——模拟股票价格实时推送： // server.js import http from 'node:http'; const PORT = 3000; // 模拟股票价格波动 function generatePrice() { return (100 + Math.random() * 10).toFixed(2); } const server = http.createServer((req, res) => { if (req.url === '/events') { // 设置 SSE 响应头 res.writeHead(200, { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache', 'Connection': 'keep-alive', 'X-Accel-Buffering': 'no', // 禁用 Nginx 缓冲 }); // 发送初始连接确认 res.write(`data: ${JSON.stringify({ connected: true })}

`); // 每秒推送一次价格 const intervalId = setInterval(() => { const price = generatePrice(); res.write(`data: ${JSON.stringify({ price, ts: Date.now() })}

`); }, 1000); // 客户端断开时清理 req.on('close', () => { clearInterval(intervalId); console.log('客户端断开连接'); }); } else { res.writeHead(200, { 'Content-Type': 'text/html' }); res.end(` <!DOCTYPE html> <html> <body> <h2>实时股价</h2> <div id="price">连接中...</div> <script> const source = new EventSource('/events'); source.onmessage = (e) => { const data = JSON.parse(e.data); document.getElementById('price').textContent = '¥' + data.price; }; source.onerror = () => { document.getElementById('price').textContent = '重连中...'; }; </script> </body> </html> `); } }); server.listen(PORT, () => { console.log(`SSE 服务运行在 http://localhost:${PORT}`); }); 运行后访问 http://localhost:3000，你会看到价格每秒更新——总共不到 30 行核心代码。

生产级封装：带心跳和重连的 SSE 中间件 上面的例子能跑，但生产环境还需要心跳保活和断线续传。下面是一个 Express 中间件封装： // sse-middleware.js class SSEConnection { constructor(res, id) { this.res = res; this.id = id; this.alive = true; } send(event, data) { if (!this.alive) return; if (event) this.res.write(`event: ${event}
`); this.res.write(`id: ${this.id}
